   105          res[rc++] = b64[ bin[byteNo] >> 2 ] ;
   106          res[rc++] = b64[ (0x3&bin[byteNo])<<4 ] ;
   107          res[rc++] = '=';
   108          res[rc++] = '=';
   109      }
