   112          res[rc++]  = b64[ bin[byteNo] >> 2 ] ;
   113          res[rc++]  = b64[ ((0x3&bin[byteNo])<<4)   +   (bin[byteNo+1] >> 4) ] ;
   114          res[rc++]  = b64[ (0x0f&bin[byteNo+1])<<2 ] ;
   115          res[rc++] = '=';
   116      }
   117
   118      res[rc]=0; // NULL TERMINATOR! ;)
   119      return res ;
   120  }
